using System;
using System.Collections.Generic;
using System.IO;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows;
using Microsoft.Web.WebView2.Wpf;
using TranslateDesktop;
class VerifySpelling {
 [STAThread]static int Main(string[] args){var reports=new List<string>();int exit=1;var app=new Application();var window=new MainWindow(false){Opacity=0,ShowActivated=false};window.Loaded+=async delegate{
  try{
   foreach(string word in new[]{"Предпринимател","recieve","salomm","Ukrayina","қазақша","你号","こんいちは","안녕하새요","Französisch","bonjour","español"}){var tokens=GeminiSpelling.Tokens(word);Check(tokens.Length==1&&tokens[0].text==word,"Unicode token: "+word,reports);}
   string emoji="🙂 Превет!";var token=GeminiSpelling.Tokens(emoji)[0];Check(token.start==3&&token.end==9,"UTF-16 offsets after emoji",reports);
   Check(GeminiSpelling.Tokens("o‘zbekcha g'isht oʻzbekiston").Length==3,"Uzbek apostrophes stay inside words",reports);
   var parsed=GeminiSpelling.ParseResponse(Fixture(new[]{new{tokenId=0,replacement="Привет"}}),emoji);Check(parsed.Length==1&&parsed[0].start==3&&parsed[0].replacement=="Привет","punctuation-safe response mapping",reports);
   Check(GeminiSpelling.ParseResponse(Fixture(new[]{new{tokenId=99,replacement="bad"},new{tokenId=0,replacement="<script>"}}),"helo").Length==0,"invalid model suggestions rejected",reports);
   var view=(WebView2CompositionControl)typeof(MainWindow).GetField("view",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window);for(int i=0;i<100;i++){await Task.Delay(100);if((bool)typeof(MainWindow).GetField("ready",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(window))break;}window.ShowTranslator();await Task.Delay(120);
   await view.CoreWebView2.ExecuteScriptAsync("window.spellMessages=[];window.nativePost=chrome.webview.postMessage.bind(chrome.webview);chrome.webview.postMessage=m=>{spellMessages.push(m);if(!['spellcheck','translate'].includes(m.type))nativePost(m)}");
   Init(view,true,"Google Api");await Task.Delay(50);
   await SetText(view,"Предпринимател");await Task.Delay(1250);int request=await RequestId(view,"spellcheck");
   Reply(view,request,"Предпринимател",new[]{new SpellingCorrection{start=0,end="Предпринимател".Length,original="Предпринимател",replacement="Предприниматель"}});await Task.Delay(100);
   Check(await Yes(view,"document.querySelector('.to-input').value==='Предпринимател'&&document.querySelector('.to-spelling-hint').textContent==='Предприниматель'"),"inline correction does not enter input value",reports);
   await view.CoreWebView2.ExecuteScriptAsync("document.querySelector('.to-input').setSelectionRange(0,document.querySelector('.to-input').value.length);window.copyData=new DataTransfer();document.querySelector('.to-input').dispatchEvent(new ClipboardEvent('copy',{clipboardData:copyData,bubbles:true,cancelable:true}))");Check(await Yes(view,"copyData.getData('text/plain')==='Предпринимател'"),"copy excludes unaccepted suggestion",reports);
   await view.CoreWebView2.ExecuteScriptAsync("document.querySelector('.to-input').setSelectionRange(document.querySelector('.to-input').value.length)");await Capture(view,args[0]);await Click(view,".to-spelling-hint");await Task.Delay(100);Check(await Yes(view,"document.querySelector('.to-input').value==='Предприниматель'&&!document.querySelector('.to-spelling-hint')"),"click replaces original word once",reports);
   await view.CoreWebView2.ExecuteScriptAsync("document.querySelector('.to-input').dispatchEvent(new KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true,cancelable:true}))");await Task.Delay(50);Check(await Yes(view,"document.querySelector('.to-input').value==='Предпринимател'"),"Ctrl+Z restores word before correction",reports);
   await SetText(view,"salomm dunyo");await Task.Delay(1250);int uzRequest=await RequestId(view,"spellcheck");await SetText(view,"recieve");Reply(view,uzRequest,"salomm dunyo",new[]{new SpellingCorrection{start=0,end=6,original="salomm",replacement="salom"}});await Task.Delay(100);Check(await Yes(view,"!document.querySelector('.to-spelling-hint')&&document.querySelector('.to-input').value==='recieve'"),"stale reply cannot change newer text",reports);
   await Task.Delay(1150);int enRequest=await RequestId(view,"spellcheck");Reply(view,enRequest,"recieve",new[]{new SpellingCorrection{start=0,end=7,original="recieve",replacement="receive"}});await Task.Delay(50);
   await view.CoreWebView2.ExecuteScriptAsync("document.querySelector('form').dispatchEvent(new Event('submit',{cancelable:true,bubbles:true}))");await Task.Delay(50);Check(await Yes(view,"spellMessages.filter(x=>x.type==='translate').at(-1).text==='recieve'&&!document.querySelector('.to-spelling-hint')"),"translation excludes suggestion and cancels spelling",reports);
   int translation=await RequestId(view,"translate");view.CoreWebView2.PostWebMessageAsJson(Json.Serializer.Serialize(new{type="translation",requestId=translation,ok=true,text="получать",source="en",target="ru"}));await Task.Delay(100);Reply(view,enRequest,"recieve",new[]{new SpellingCorrection{start=0,end=7,original="recieve",replacement="receive"}});Check(await Yes(view,"document.querySelector('.to-input').value==='получать'&&!document.querySelector('.to-spelling-hint')"),"completed translation is not decorated by old replies",reports);
   Init(view,true,"Offline");await Task.Delay(50);await view.CoreWebView2.ExecuteScriptAsync("spellMessages=[]");await SetText(view,"salomm");await Task.Delay(1250);Check(await Yes(view,"!spellMessages.some(x=>x.type==='spellcheck')"),"Offline never sends spelling requests",reports);
   Init(view,false,"Google Api");await Task.Delay(50);await SetText(view,"helo");await Task.Delay(1250);Check(await Yes(view,"!spellMessages.some(x=>x.type==='spellcheck')"),"disabled spellcheck never sends requests",reports);
   Init(view,true,"Google Api");await Task.Delay(50);await SetText(view,"Превет, мирр!");await Task.Delay(1250);int two=await RequestId(view,"spellcheck");Reply(view,two,"Превет, мирр!",new[]{new SpellingCorrection{start=0,end=6,original="Превет",replacement="Привет"},new SpellingCorrection{start=8,end=12,original="мирр",replacement="мир"}});await Task.Delay(70);await Click(view,".to-spelling-hint");await Task.Delay(60);Check(await Yes(view,"document.querySelector('.to-input').value==='Привет, мирр!'&&document.querySelectorAll('.to-spelling-hint').length===1"),"accepting one suggestion preserves another",reports);await Click(view,".to-spelling-hint");Check(await Yes(view,"document.querySelector('.to-input').value==='Привет, мир!'"),"multiple corrections preserve punctuation",reports);
   await SetText(view,"one");await view.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.insertText",Json.Serializer.Serialize(new{text=" two"}));Check(await Yes(view,"document.querySelector('.to-input').value==='one two'"),"native typing edits plain text",reports);
   await Key(view,"Backspace",8,0);Check(await Yes(view,"document.querySelector('.to-input').value==='one tw'"),"native Backspace keeps editor value synchronized",reports);
   await Key(view,"Enter",13,8);await view.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.insertText",Json.Serializer.Serialize(new{text="你好"}));Check(await Yes(view,"document.querySelector('.to-input').value==='one tw\\n你好'"),"Shift+Enter and native Chinese input preserve newlines: "+await view.CoreWebView2.ExecuteScriptAsync("JSON.stringify({value:document.querySelector('.to-input').value,html:document.querySelector('.to-input').innerHTML})"),reports);
   await view.CoreWebView2.ExecuteScriptAsync("document.querySelector('.to-input').setSelectionRange(0,6);window.pasteData=new DataTransfer();pasteData.setData('text/plain','Hello');document.querySelector('.to-input').dispatchEvent(new ClipboardEvent('paste',{clipboardData:pasteData,bubbles:true,cancelable:true}))");Check(await Yes(view,"document.querySelector('.to-input').value==='Hello\\n你好'"),"plain-text paste preserves Unicode and selection",reports);
   await view.CoreWebView2.ExecuteScriptAsync("const e=document.querySelector('.to-input');e.value='你号';e.setSelectionRange(2);e.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));e.dispatchEvent(new Event('input',{bubbles:true}));spellMessages=[]");await Task.Delay(1250);Check(await Yes(view,"!spellMessages.some(x=>x.type==='spellcheck')"),"IME composition pauses spellcheck",reports);
   await view.CoreWebView2.ExecuteScriptAsync("document.querySelector('.to-input').dispatchEvent(new CompositionEvent('compositionend',{bubbles:true}))");await Task.Delay(1250);Check(await Yes(view,"spellMessages.some(x=>x.type==='spellcheck'&&x.text==='你号')"),"IME completion schedules spellcheck",reports);
   Check(window.IsVisible,"spelling interactions keep native window visible",reports);exit=0;
  }catch(Exception ex){reports.Add("FAIL "+ex.ToString());}finally{File.WriteAllLines(args[0],reports);window.Close();}
 };var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromSeconds(30)};timer.Tick+=delegate{File.WriteAllText(args[0],"FAIL spelling test timeout");window.Close();};timer.Start();app.Run(window);timer.Stop();return exit;}
 static void Init(WebView2CompositionControl view,bool enabled,string provider){view.CoreWebView2.PostWebMessageAsJson(Json.Serializer.Serialize(new{type="init",language="en",provider,offlineReady=true,hasGoogleKey=true,spellcheckEnabled=enabled,systemLanguage="en",uiLanguage="en",hotkey="Win+0",winZeroEnabled=true}));}
 static async Task SetText(WebView2CompositionControl view,string text){await view.CoreWebView2.ExecuteScriptAsync("(()=>{const e=document.querySelector('.to-input');e.value="+Json.Serializer.Serialize(text)+";e.focus({preventScroll:true});e.setSelectionRange(e.value.length);e.dispatchEvent(new Event('input',{bubbles:true}));})()");}
 static async Task<int> RequestId(WebView2CompositionControl view,string type){return int.Parse(await view.CoreWebView2.ExecuteScriptAsync("spellMessages.filter(x=>x.type==="+Json.Serializer.Serialize(type)+").at(-1).requestId"));}
 static void Reply(WebView2CompositionControl view,int id,string text,SpellingCorrection[] corrections){view.CoreWebView2.PostWebMessageAsJson(Json.Serializer.Serialize(new{type="spelling",requestId=id,text,ok=true,corrections}));}
 static string Fixture(object corrections){return Json.Serializer.Serialize(new{candidates=new[]{new{finishReason="STOP",content=new{parts=new[]{new{text=Json.Serializer.Serialize(new{language="ru",corrections})}}}}}});}
 static async Task<bool> Yes(WebView2CompositionControl view,string script){return await view.CoreWebView2.ExecuteScriptAsync(script)=="true";}
 static async Task Key(WebView2CompositionControl view,string key,int code,int modifiers){foreach(string type in new[]{"keyDown","keyUp"})await view.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.dispatchKeyEvent",Json.Serializer.Serialize(new{type,key,code=key,windowsVirtualKeyCode=code,modifiers,text=type=="keyDown"&&key=="Enter"?"\r":""}));}
 static void Check(bool condition,string message,List<string> reports){if(!condition)throw new Exception(message);reports.Add("PASS "+message);}
 static async Task Click(WebView2CompositionControl view,string selector){double[] point=Json.Serializer.Deserialize<double[]>(await view.CoreWebView2.ExecuteScriptAsync("(()=>{const r=document.querySelector("+Json.Serializer.Serialize(selector)+").getBoundingClientRect();return [r.left+r.width/2,r.top+r.height/2]})()"));foreach(string type in new[]{"mousePressed","mouseReleased"})await view.CoreWebView2.CallDevToolsProtocolMethodAsync("Input.dispatchMouseEvent",Json.Serializer.Serialize(new{type,x=point[0],y=point[1],button="left",clickCount=1}));}
 static async Task Capture(WebView2CompositionControl view,string report){double[] size=Json.Serializer.Deserialize<double[]>(await view.CoreWebView2.ExecuteScriptAsync("[innerWidth,Math.ceil(document.querySelector('form').getBoundingClientRect().bottom+25)]"));string result=await view.CoreWebView2.CallDevToolsProtocolMethodAsync("Page.captureScreenshot",Json.Serializer.Serialize(new{format="png",captureBeyondViewport=false,clip=new{x=0,y=0,width=size[0]*view.ZoomFactor,height=size[1]*view.ZoomFactor,scale=1}}));File.WriteAllBytes(Path.ChangeExtension(report,".png"),Convert.FromBase64String(Json.String(Json.Parse(result),"data")));}
}
